// Détection automatique de l'IP et du port Flask
const { execSync } = require('child_process');
const os = require('os');

// Méthode 1: Détecter l'IP locale
function getLocalIP() {
  const interfaces = os.networkInterfaces();
  for (const name of Object.keys(interfaces)) {
    for (const interface of interfaces[name]) {
      if (interface.family === 'IPv4' && !interface.internal) {
        return interface.address;
      }
    }
  }
  return '127.0.0.1';
}

// Méthode 2: Tester les ports communs
function testFlaskPort(ip) {
  const ports = [5003, 5002, 5000, 5001];

  for (const port of ports) {
    try {
      const testUrl = `http://${ip}:${port}/api/config`;
      // Note: Dans n8n, on ne peut pas faire de requête HTTP synchrone ici
      // On va donc construire l'URL avec les bonnes pratiques
      console.log(`Testing: ${testUrl}`);
      return { ip, port, url: `http://${ip}:${port}` };
    } catch (e) {
      continue;
    }
  }

  // Fallback vers le port par défaut
  return { ip, port: 5003, url: `http://${ip}:5003` };
}

const localIP = getLocalIP();
const flaskConfig = testFlaskPort(localIP);

console.log('🌐 IP détectée:', localIP);
console.log('🔧 Configuration Flask:', flaskConfig);

// Passer les données + configuration dynamique
return {
  json: {
    flask_config: flaskConfig,
    form_data: $input.item.json,
    dynamic_url: {
      base: flaskConfig.url,
      create_layout: `${flaskConfig.url}/api/create-layout-urls`,
      download_base: `${flaskConfig.url}/api/download/`
    }
  }
};

// Traitement des images du formulaire pour Google Drive
const items = [];
const binaryData = $input.item.json.form_data.binary;
const flaskConfig = $input.item.json.flask_config;

// Debug
console.log('🔧 Flask URL détectée:', flaskConfig.url);
console.log('Binary data keys:', Object.keys(binaryData || {}));

// Traiter chaque image uploadée
if (binaryData) {
  Object.entries(binaryData).forEach(([key, data], index) => {
    console.log(`Processing image ${index + 1}:`, key);

    // Créer un item pour chaque image avec le bon format pour Google Drive
    items.push({
      json: {
        fileName: data.fileName || `image_${index + 1}`,
        mimeType: data.mimeType || 'image/jpeg',
        flask_config: flaskConfig // Passer la config à travers le pipeline
      },
      binary: {
        data: data
      }
    });
  });
}

if (items.length === 0) {
  // Aucune image trouvée, passer quand même avec la config
  return [{ json: { 
    message: 'Aucune image à uploader',
    flask_config: flaskConfig
  }}];
}

console.log(`Préparation de ${items.length} images pour Google Drive`);
return items;

// Passer les données Drive + Formulaire vers OpenAI + Config Flask
const driveResults = $input.item.json;
const formData = $node["🌐 Détecteur IP Automatique"].json.form_data;
const flaskConfig = $node["🌐 Détecteur IP Automatique"].json.flask_config;

console.log('🔧 Configuration Flask transmise:', flaskConfig);
console.log('Drive results received:', driveResults);
console.log('Form data:', formData);

// Créer les URLs Google Drive
let imageUrls = [];
let imageCount = 0;

if (Array.isArray(driveResults)) {
  // Plusieurs fichiers uploadés
  imageUrls = driveResults.map(file => `https://drive.google.com/uc?id=${file.id}`);
  imageCount = driveResults.length;
} else if (driveResults && driveResults.id) {
  // Un seul fichier uploadé
  imageUrls = [`https://drive.google.com/uc?id=${driveResults.id}`];
  imageCount = 1;
}

console.log('Images URLs créées:', imageUrls);

// Retourner les données pour OpenAI avec les infos Drive + Config Flask
return {
  json: {
    contenu: formData.contenu,
    flask_config: flaskConfig,
    drive_info: {
      image_urls: imageUrls,
      image_count: imageCount,
      drive_response: driveResults
    }
  }
};

// Traitement final : combiner IA + Drive + Config Flask Dynamique
const aiResponse = $input.item.json.text;
const previousData = $node["Préparation pour IA"].json;
const formData = $node["🌐 Détecteur IP Automatique"].json.form_data;
const flaskConfig = $node["🌐 Détecteur IP Automatique"].json.flask_config;

console.log('🔧 Configuration Flask finale:', flaskConfig);
console.log('AI Response:', aiResponse);
console.log('Previous data:', previousData);

// Parser la réponse JSON d'OpenAI
let analysis;
try {
  const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
  console.log('Cleaned AI response:', cleanResponse);
  analysis = JSON.parse(cleanResponse);
  console.log('Parsed analysis:', analysis);
} catch (e) {
  console.log('❌ Parsing failed:', e.message);
  console.log('❌ Raw response:', aiResponse);
  analysis = {
    title: 'Erreur parsing IA',
    subtitle: 'Erreur parsing IA',
    body: formData.contenu || 'Erreur parsing IA'
  };
}

// Récupérer les infos Drive
const driveInfo = previousData.drive_info;
const imageUrls = driveInfo.image_urls;
const imageCount = driveInfo.image_count;

console.log('✅ Images uploadées sur Drive:', imageCount);
console.log('✅ URLs générées:', imageUrls);
console.log('✅ Analyse IA titre:', analysis.title);
console.log('✅ Analyse IA sous-titre:', analysis.subtitle);

// Sélectionner le template
let template;
if (imageCount === 1) {
  template = 'template-mag-simple-1808';
} else if (imageCount >= 3) {
  template = 'template-mag-simple-2-1808';
} else {
  template = 'template-mag-simple-1808';
}

// Retourner les données structurées avec config Flask dynamique
return {
  ai_analysis: {
    title: analysis.title,
    subtitle: analysis.subtitle,
    body: analysis.body
  },
  template_selection: {
    template: template,
    image_count: imageCount,
    reason: imageCount === 1 ? '1 image détectée' : imageCount >= 3 ? imageCount + ' images détectées' : 'Défaut'
  },
  google_drive: {
    image_urls: imageUrls,
    upload_count: imageCount
  },
  flask_config: flaskConfig,
  dynamic_urls: {
    create_layout: `${flaskConfig.url}/api/create-layout-urls`,
    download_base: `${flaskConfig.url}/api/download/`
  },
  original_content: formData.contenu,
  debug: {
    ai_raw_response: aiResponse,
    drive_response: driveInfo.drive_response,
    detected_ip: flaskConfig.ip,
    detected_port: flaskConfig.port
  }
};

