if (response.success) {
  return {
    status: 'success',
    message: '🎉 Document créé avec URL dynamique + Google Drive + IA !',
    details: {
      flask_config: {
        detected_ip: flaskConfig.ip,
        detected_port: flaskConfig.port,
        used_url: flaskConfig.url
      },
      template_used: aiData.template_selection.template,
      template_reason: aiData.template_selection.reason,
