      drive_urls: aiData.google_drive.image_urls,
      ai_analysis: {
        title: aiData.ai_analysis?.title || '⚠️ Titre non extrait par l\'IA',
        subtitle: aiData.ai_analysis?.subtitle || '⚠️ Sous-titre non extrait par l\'IA',
        body_preview: (aiData.ai_analysis?.body || 'Contenu non analysé').substring(0, 100) + '...'
      },
      debug_raw_ai: aiData.debug?.ai_raw_response
    },
    project_id: response.project_id,
    download_url: `${aiData.dynamic_urls.download_base}${response.project_id}`
  };
} else {
  return {
    status: 'error',
    message: '❌ Erreur: ' + (response.error || 'Erreur inconnue'),
    flask_config: flaskConfig,
    ai_data: aiData,
    debug_info: response
  };
}
